// ══════════════════════════════════════════════════════════════
//  ISLAND VIEW — Drop-in replacement for renderStore()
//  Paste this ENTIRE block into app_min.js,
//  replacing the old renderStore function and its CSS.
// ══════════════════════════════════════════════════════════════

// ── Island CSS (add to the CSS string in app_min.js) ─────────
var ISLAND_CSS =
  // island wrapper
  "#secHome{background:linear-gradient(180deg,#87ceeb 0%,#5ba3d4 30%,#1c6aa6 100%);min-height:calc(100vh - 130px);overflow:hidden}" +
  ".island-wrap{position:relative;width:100%;padding-bottom:12px}" +

  // stats bar
  ".isl-stats{display:flex;gap:8px;padding:10px 12px 0}" +
  ".isl-stat{flex:1;background:rgba(0,0,0,.28);border:1px solid rgba(255,255,255,.18);border-radius:14px;padding:8px 10px;color:#fff}" +
  ".isl-stat .sk{font-size:10px;opacity:.75;font-weight:700;display:block}" +
  ".isl-stat .sv{font-size:14px;font-weight:800}" +

  // collect bar
  ".isl-collect{display:flex;align-items:center;gap:10px;padding:10px 12px}" +
  ".isl-cinfo{flex:1;background:rgba(0,0,0,.28);border:1px solid rgba(255,255,255,.18);border-radius:14px;padding:9px 12px;color:#fff}" +
  ".isl-cinfo .ck{font-size:10px;opacity:.75;font-weight:700}" +
  ".isl-cinfo .cv{font-size:16px;font-weight:800;display:flex;align-items:center;gap:5px}" +
  ".isl-cbtn{background:linear-gradient(180deg,#f5b316,#d6921a);border:none;color:#fff;border-radius:16px;padding:11px 22px;font-weight:800;font-size:15px;cursor:pointer;box-shadow:0 3px 0 #a26b0e;white-space:nowrap;display:flex;align-items:center;gap:6px}" +
  ".isl-cbtn:disabled{filter:grayscale(.4);box-shadow:none;opacity:.8}" +

  // the island scene
  ".isl-scene{position:relative;width:100%;aspect-ratio:.88/1;margin:0 auto;max-width:480px}" +

  // ocean rings
  ".isl-ocean{position:absolute;inset:0;border-radius:50% 50% 50% 50%/45% 45% 55% 55%;background:radial-gradient(ellipse 80% 55% at 50% 52%,#1a7ab5 60%,#0d5a8a 100%);animation:waveAnim 4s ease-in-out infinite}" +
  "@keyframes waveAnim{0%,100%{transform:scaleX(1)}50%{transform:scaleX(1.012)}}" +
  ".isl-ocean-ring{position:absolute;border-radius:50%;border:2px solid rgba(255,255,255,.15);animation:ringAnim 3s ease-in-out infinite}" +
  "@keyframes ringAnim{0%,100%{opacity:.15;transform:scale(1)}50%{opacity:.3;transform:scale(1.01)}}" +

  // grass island base
  ".isl-base{position:absolute;left:8%;right:8%;top:5%;bottom:5%;border-radius:50% 50% 50% 50%/45% 45% 55% 55%;background:radial-gradient(ellipse 90% 80% at 50% 48%,#5aad3a 0%,#3d8a25 55%,#2d6b18 100%);box-shadow:0 8px 24px rgba(0,0,0,.35)}" +
  ".isl-sand{position:absolute;left:12%;right:12%;top:10%;bottom:10%;border-radius:50% 50% 50% 50%/45% 45% 55% 55%;background:radial-gradient(ellipse 80% 70% at 50% 50%,#e8c87a 0%,#c8a855 60%,transparent 100%);opacity:.35}" +

  // paths on island
  ".isl-path{position:absolute;background:rgba(200,168,85,.45);border-radius:50%}" +

  // asset nodes
  ".isl-node{position:absolute;display:flex;flex-direction:column;align-items:center;cursor:pointer;transform:translate(-50%,-50%);z-index:3}" +
  ".isl-node:active{transform:translate(-50%,-50%) scale(.93)}" +
  ".isl-img-wrap{position:relative;width:var(--sz);height:var(--sz)}" +
  ".isl-img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 4px 6px rgba(0,0,0,.4));transition:filter .3s}" +
  ".isl-node.locked .isl-img{filter:grayscale(1) brightness(.55) drop-shadow(0 2px 4px rgba(0,0,0,.5))}" +
  ".isl-lock{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:calc(var(--sz) * .38);pointer-events:none}" +
  ".isl-node.locked .isl-lock{display:flex}" +
  ".isl-node:not(.locked) .isl-lock{display:none}" +
  ".isl-lv{background:linear-gradient(180deg,#5cb432,#3a8a2a);color:#fff;font-size:9px;font-weight:800;padding:1px 7px;border-radius:8px;margin-top:2px;box-shadow:0 1px 3px rgba(0,0,0,.3);white-space:nowrap}" +
  ".isl-lv.buyable{background:linear-gradient(180deg,#f5b316,#d6921a)}" +
  ".isl-lv.locked-lbl{background:rgba(0,0,0,.45);color:rgba(255,255,255,.6)}" +

  // buy pulse
  ".isl-node.buyable .isl-img{animation:buyPulse 2s ease-in-out infinite}" +
  "@keyframes buyPulse{0%,100%{filter:drop-shadow(0 4px 6px rgba(0,0,0,.4)) drop-shadow(0 0 0px rgba(245,179,22,0))}50%{filter:drop-shadow(0 4px 6px rgba(0,0,0,.4)) drop-shadow(0 0 10px rgba(245,179,22,.9))}}" +

  // upgrade dots
  ".isl-dots{display:flex;gap:2px;margin-top:2px}" +
  ".isl-dot{width:5px;height:5px;border-radius:50%;background:rgba(255,255,255,.35)}" +
  ".isl-dot.on{background:#f5b316}" +

  // tap ripple
  "@keyframes ripple{0%{transform:translate(-50%,-50%) scale(0);opacity:.6}100%{transform:translate(-50%,-50%) scale(2.5);opacity:0}}" +
  ".isl-ripple{position:absolute;width:var(--sz);height:var(--sz);border-radius:50%;border:2px solid #f5b316;pointer-events:none;animation:ripple .5s ease-out forwards}" +

  // bottom hint
  ".isl-hint{text-align:center;font-size:11px;color:rgba(255,255,255,.55);padding:6px 0 4px;font-weight:600}";

// ── Asset positions on island (left%, top% = center of asset) ─
//  Calibrated for a ~380px wide scene, isometric-ish layout
var ISLAND_POSITIONS = {
  "coconut_tree":   { l:28, t:22, sz:52 },
  "banana_tree":    { l:62, t:18, sz:50 },
  "mango_tree":     { l:46, t:14, sz:54 },
  "fishing_dock":   { l:78, t:28, sz:58 },
  "fisher_house":   { l:72, t:46, sz:60 },
  "seafood_market": { l:48, t:32, sz:62 },
  "small_hut":      { l:24, t:42, sz:58 },
  "beach_shop":     { l:26, t:60, sz:62 },
  "fruit_market":   { l:52, t:56, sz:64 },
  "potion_shop":    { l:74, t:65, sz:60 },
  "resort_hotel":   { l:48, t:72, sz:66 },
  "vip_island_club":{ l:48, t:88, sz:70 }
};

// ── Island View HTML builder ──────────────────────────────────
function buildIslandHTML(cat, userAssets, incomePerHour, pendingCoins, offlineHours, coins) {
  var maxDots = 5;

  var nodesHTML = cat.map(function(a) {
    var type  = a.type;
    var lv    = (userAssets || {})[type] || 0;
    var owned = lv > 0;
    var buyable = !owned && incomePerHour >= a.unlock;
    var locked  = !owned && !buyable;
    var pos   = ISLAND_POSITIONS[type] || { l:50, t:50, sz:56 };
    var sz    = pos.sz + 'px';

    var stateClass = locked ? 'locked' : (buyable ? 'buyable' : '');

    // dots (upgrade progress, max 5 shown)
    var dotsHTML = '';
    if (owned) {
      var dotCount = Math.min(lv, maxDots);
      var dots = '';
      for (var d = 0; d < maxDots; d++) {
        dots += '<div class="isl-dot' + (d < dotCount ? ' on' : '') + '"></div>';
      }
      dotsHTML = '<div class="isl-dots">' + dots + '</div>';
    }

    // label
    var lbl = locked
      ? '<div class="isl-lv locked-lbl">🔒</div>'
      : owned
        ? '<div class="isl-lv">Lv.' + lv + '</div>'
        : '<div class="isl-lv buyable">BUY</div>';

    return '<div class="isl-node ' + stateClass + '" ' +
      'style="left:' + pos.l + '%;top:' + pos.t + '%;--sz:' + sz + '" ' +
      'data-type="' + escapeHtml(type) + '" ' +
      'data-owned="' + (owned?'1':'0') + '" ' +
      'data-buyable="' + (buyable?'1':'0') + '">' +
      '<div class="isl-img-wrap">' +
        '<img class="isl-img" src="' + encodeURI(IMG_BASE + a.img) + '" alt="' + escapeHtml(a.name) + '" ' +
          'onerror="this.src=\'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%2248%22 height=%2248%22><rect width=%2248%22 height=%2248%22 rx=%228%22 fill=%22%23ffffff22%22/><text x=%2224%22 y=%2232%22 text-anchor=%22middle%22 font-size=%2220%22>🏗️</text></svg>\'">' +
        '<div class="isl-lock">🔒</div>' +
      '</div>' +
      lbl +
      dotsHTML +
    '</div>';
  }).join('');

  return (
    // Stats row
    '<div class="isl-stats">' +
      '<div class="isl-stat"><span class="sk">⚡ Income</span><span class="sv">' + fmtNum(incomePerHour) + '/h</span></div>' +
      '<div class="isl-stat"><span class="sk">⏱ Offline</span><span class="sv">' + offlineHours + 'h<button onclick="openUpgOffline()" style="background:linear-gradient(180deg,#5cb432,#3a8a2a);border:none;color:#fff;border-radius:6px;width:18px;height:18px;font-size:12px;font-weight:800;cursor:pointer;margin-left:5px;vertical-align:middle;line-height:1">+</button></span></div>' +
    '</div>' +

    // Collect bar
    '<div class="isl-collect">' +
      '<div class="isl-cinfo">' +
        '<div class="ck">Profit Accumulated ℹ️</div>' +
        '<div class="cv">🪙 <span id="pendCoins">' + fmtNum(pendingCoins) + '</span> Coins</div>' +
      '</div>' +
      '<button class="isl-cbtn" id="btnCollect" ' + (pendingCoins <= 0 ? 'disabled' : '') + ' onclick="doCollect()">💰 Collect</button>' +
    '</div>' +

    // Island scene
    '<div class="isl-scene">' +
      // ocean
      '<div class="isl-ocean"></div>' +
      '<div class="isl-ocean-ring" style="inset:-2%;"></div>' +
      '<div class="isl-ocean-ring" style="inset:-5%;opacity:.08;animation-delay:.8s"></div>' +
      // grass + sand
      '<div class="isl-base"></div>' +
      '<div class="isl-sand"></div>' +
      // dirt paths
      '<div class="isl-path" style="left:40%;top:35%;width:22%;height:38%;opacity:.5"></div>' +
      '<div class="isl-path" style="left:25%;top:50%;width:50%;height:22%;opacity:.4"></div>' +
      // asset nodes
      nodesHTML +
    '</div>' +

    '<div class="isl-hint">Tap an asset to buy or upgrade</div>'
  );
}

// ── Updated renderStore (island mode) ────────────────────────
function renderIslandStore() {
  var cat  = state.data.catalog || [];
  var u    = state.user;
  var isl  = state.data.island;
  var per  = isl.incomePerHour;

  var box = document.getElementById('storeGrid');
  if (!box) return;

  box.style.display = 'block';
  box.style.padding = '0';
  box.style.gridTemplateColumns = 'unset';
  box.style.gap = 'unset';

  box.innerHTML = buildIslandHTML(cat, u.assets, per, isl.pendingCoins, u.offlineHours, u.coins);

  // node tap handlers
  box.querySelectorAll('.isl-node').forEach(function(node) {
    node.onclick = function(e) {
      var type    = node.dataset.type;
      var owned   = node.dataset.owned === '1';
      var buyable = node.dataset.buyable === '1';

      // ripple effect
      var ripple = document.createElement('div');
      ripple.className = 'isl-ripple';
      ripple.style.left = '50%'; ripple.style.top = '50%';
      node.querySelector('.isl-img-wrap').appendChild(ripple);
      setTimeout(function(){ ripple.remove(); }, 500);

      if (buyable) {
        openBuyModal(type);
      } else if (owned) {
        openUpgradeModal(type);
      } else {
        openLockedModal(type);
      }
    };
  });
}

// ── Modals for island tap actions ─────────────────────────────
function openBuyModal(type) {
  var a = findCat(type); if (!a) return;
  var afford = state.user.coins >= a.buyCost;
  var html =
    '<div style="text-align:center;margin-bottom:12px">' +
      '<img src="' + encodeURI(IMG_BASE + a.img) + '" style="width:90px;height:90px;object-fit:contain" onerror="this.style.display=\'none\'">' +
    '</div>' +
    '<div style="text-align:center;margin-bottom:6px;font-size:14px;color:#5a6d80">Earns <b style="color:#23311f">+' + fmtNum(a.baseIncome) + '</b> coins/h at Lv.1</div>' +
    '<div style="text-align:center;margin-bottom:14px;font-size:22px;font-weight:800">🪙 ' + fmtNum(a.buyCost) + '</div>' +
    '<button class="btn" id="mBuyBtn"' + (afford?'':' disabled') + '>Buy ' + escapeHtml(a.name) + '</button>' +
    (!afford ? '<div style="text-align:center;font-size:12px;color:#e44e4e;margin-top:8px">Need ' + fmtNum(a.buyCost - state.user.coins) + ' more coins</div>' : '');
  openModal('🏗️ ' + escapeHtml(a.name), html);
  document.getElementById('mBuyBtn').onclick = function(){ closeModal(); doBuy(type); };
}

function openUpgradeModal(type) {
  var a  = findCat(type); if (!a) return;
  var lv = (state.user.assets || {})[type] || 0;
  var maxLv  = state.data.maxAssetLevel || 30;
  var atMax  = lv >= maxLv;
  var cur    = assetIncome(type, lv);
  var cost   = upgradeCostOf(type, lv);
  var afford = state.user.coins >= cost;
  var nextInc = atMax ? cur : assetIncome(type, lv + 1);
  var html =
    '<div style="text-align:center;margin-bottom:10px">' +
      '<img src="' + encodeURI(IMG_BASE + a.img) + '" style="width:80px;height:80px;object-fit:contain" onerror="this.style.display=\'none\'">' +
    '</div>' +
    '<div style="display:flex;justify-content:space-around;margin-bottom:12px">' +
      '<div style="text-align:center"><div style="font-size:11px;color:#5a6d80">Level</div><div style="font-weight:800;font-size:18px">' + lv + '</div></div>' +
      '<div style="text-align:center"><div style="font-size:11px;color:#5a6d80">Income/h</div><div style="font-weight:800;font-size:18px">🪙 ' + fmtNum(cur) + '</div></div>' +
    '</div>';
  if (atMax) {
    html += '<button class="btn" disabled>MAX LEVEL</button>';
  } else {
    html +=
      '<div style="text-align:center;margin-bottom:8px;font-size:13px;color:#5a6d80">Lv.' + lv + ' → Lv.' + (lv+1) + ' &nbsp; Income: <b style="color:#3a8a2a">+' + fmtNum(nextInc - cur) + '/h</b></div>' +
      '<div style="text-align:center;margin-bottom:14px;font-size:20px;font-weight:800">🪙 ' + fmtNum(cost) + '</div>' +
      '<button class="btn" id="mUpgBtn"' + (afford?'':' disabled') + '>Upgrade</button>' +
      (!afford ? '<div style="text-align:center;font-size:12px;color:#e44e4e;margin-top:8px">Need ' + fmtNum(cost - state.user.coins) + ' more coins</div>' : '');
  }
  openModal('⬆️ ' + escapeHtml(a.name), html);
  if (!atMax) document.getElementById('mUpgBtn').onclick = function(){ closeModal(); doUpgrade(type); };
}

function openLockedModal(type) {
  var a = findCat(type); if (!a) return;
  var per = state.data.island.incomePerHour;
  var pct = a.unlock > 0 ? Math.min(100, Math.floor(per / a.unlock * 100)) : 0;
  var html =
    '<div style="text-align:center;margin-bottom:10px">' +
      '<img src="' + encodeURI(IMG_BASE + a.img) + '" style="width:80px;height:80px;object-fit:contain;filter:grayscale(1) brightness(.6)" onerror="this.style.display=\'none\'">' +
    '</div>' +
    '<div style="text-align:center;margin-bottom:6px;font-size:13px;color:#5a6d80">Unlock at <b style="color:#23311f">' + fmtNum(a.unlock) + '</b> coins/h income</div>' +
    '<div style="width:100%;height:10px;background:#e2e7ec;border-radius:8px;overflow:hidden;margin-bottom:6px">' +
      '<div style="height:100%;width:' + pct + '%;background:linear-gradient(90deg,#5cb432,#3a8a2a);border-radius:8px;transition:width .3s"></div>' +
    '</div>' +
    '<div style="text-align:center;font-size:12px;color:#5a6d80">' + fmtNum(per) + ' / ' + fmtNum(a.unlock) + ' (' + pct + '%)</div>';
  openModal('🔒 ' + escapeHtml(a.name), html);
}

// ══════════════════════════════════════════════════════════════
//  HOW TO INTEGRATE INTO app_min.js:
//
//  1. In the CSS string, REPLACE the line:
//     "#secHome{background:linear-gradient...}"
//     with the ISLAND_CSS variable above.
//
//  2. REPLACE the renderStore() function with renderIslandStore().
//
//  3. In render(), change:
//     renderStore();
//     to:
//     renderIslandStore();
//
//  4. In doCollect(), doUpgrade(), doBuy() callbacks, change:
//     renderStore();
//     to:
//     renderIslandStore();
//
//  5. The storeGrid div is REUSED — no HTML changes needed.
//
//  6. Make sure ISLAND_POSITIONS keys match your API's a.type values.
//     Common mappings (adjust to match your actual API):
//       coconut_tree, banana_tree, mango_tree,
//       fishing_dock, fisher_house, seafood_market,
//       small_hut, beach_shop, fruit_market,
//       potion_shop, resort_hotel, vip_island_club
// ══════════════════════════════════════════════════════════════
